/* Presentation prototype only. No network, credentials, provider SDK or production writes. */
'use strict';
const $=s=>document.querySelector(s),E=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const initial=structuredClone(window.RAPDEM_DEMO);let db=structuredClone(initial),role='admin',viewState='normal',selectedMovie=0,filterText='',filterStatus='',importCommitted=false,dirty=false,toastTimer;
const names={owner:'Chủ hệ thống',admin:'Quản trị',editor:'Biên tập',ads:'Quảng cáo',finance:'Báo cáo',support:'Hỗ trợ'};
const labels={draft:'Bản nháp',in_review:'Chờ duyệt',approved:'Đã duyệt',live:'Live mô phỏng',unpublished:'Chưa xuất bản',active:'Đang chạy · mẫu',paused:'Tạm dừng',ended:'Đã kết thúc',blocked:'Bị chặn',scheduled:'Đã lên lịch',new:'Mới tiếp nhận',triaged:'Đã phân loại',in_progress:'Đang xử lý',resolved:'Đã xử lý',closed:'Đã đóng',confirmed:'Đã xác nhận · mẫu',locked:'Đã khóa kỳ',unverified:'Chưa xác minh',supported:'Đã xác minh',unsupported:'Không hỗ trợ',pending:'Chờ xác minh',verified:'Đã kiểm tra · mẫu',clean:'Ảnh mẫu',failed:'Thất bại',queued:'Trong hàng đợi',running:'Đang thực hiện',succeeded:'Hoàn tất · mẫu',dead_letter:'Cần xử lý',cancelled:'Đã hủy'};
const badge=(value)=>`<span class="badge ${['live','active','approved','confirmed','verified','clean','succeeded','resolved'].includes(value)?'green':['in_review','pending','unverified','scheduled','queued'].includes(value)?'amber':['failed','blocked','dead_letter'].includes(value)?'red':['in_progress','running'].includes(value)?'blue':''}">${E(labels[value]||value)}</span>`;
const btn=(label,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,to,cls='')=>`<a class="${cls}" href="#${to}">${label}</a>`;
const head=(title,subtitle,actions='')=>`<div class="page-head"><div><div class="eyebrow">Rạp Đêm Studio / CMS V2</div><h1>${title}</h1><p class="muted">${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div><div class="panel-body">${body}</div></section>`;
const callout=(title,body,type='')=>`<div class="callout ${type}"><strong>${title}</strong>${body}</div>`;
const field=(label,name,value='',type='text',full=false,hint='')=>`<label class="field ${full?'full':''}"><span>${label}</span><input type="${type}" name="${name}" value="${E(value)}" ${type==='number'?'step="1"':''}><span class="field-error" data-error="${name}"></span>${hint?`<small>${hint}</small>`:''}</label>`;
const select=(label,name,options,value,full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;
const tabs=(items,active)=>`<div class="tabs">${items.map(([label,to])=>link(label,to,to===active?'active':'')).join('')}</div>`;
function table(headers,rows,footer=''){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${footer?`<div class="table-foot">${footer}</div>`:''}`;}
const detail=items=>`<dl class="detail-list">${items.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
function note(){return `<p class="footer-note">CMS V2 · Prototype cục bộ · Dữ liệu minh họa, không phải số liệu kinh doanh · Không kết nối website hoặc đối tác</p>`;}
function showToast(text,error=false){$('#toast').textContent=text;$('#toast').style.background=error?'#9d433b':'#243a2d';$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function route(){return location.hash.slice(1).split('?')[0]||'dashboard';}
const nav=[['TỔNG QUAN',[['dashboard','◫','Dashboard'],['tasks','✓','Công việc']]],['NỘI DUNG',[['movies','▤','Kho phim'],['taxonomies','≡','Danh mục'],['assets','▧','Thư viện ảnh'],['providers','◇','Nguồn phát'],['reviews','◎','Duyệt & xuất bản'],['site','◩','Giao diện website']]],['KINH DOANH',[['campaigns','◈','Quảng cáo'],['reservations','▦','Lịch quảng cáo'],['analytics','▥','Thống kê'],['statements','◷','Đối soát doanh thu']]],['VẬN HÀNH',[['reports','□','Báo lỗi & hỗ trợ'],['staff','♙','Nhân sự & quyền'],['jobs','⚙','Hệ thống']]]];
function activeNav(r){if(['movie-edit','movie-detail','episodes'].includes(r))return'movies';if(['sources','capabilities'].includes(r))return'providers';if(['review-detail','publishing','preview'].includes(r))return'reviews';if(['sections','pages'].includes(r))return'site';if(['campaign-edit','creatives','placements','ad-rules'].includes(r))return'campaigns';if(r==='reservation-new')return'reservations';if(['revenue-import','statement-detail','payments'].includes(r))return'statements';if(r==='report-detail')return'reports';if(r==='roles')return'staff';if(['settings','backups','audit','components','states'].includes(r))return'jobs';return r;}
function shell(content){const r=route();const screen=window.RAPDEM_SCREENS.find(s=>s.route===r);return `<div class="shell"><aside class="sidebar" aria-label="Điều hướng CMS"><div class="brand"><span class="brand-symbol">R</span><div><strong>RẠP ĐÊM</strong><small>MANAGEMENT STUDIO</small></div></div><nav>${nav.map(([group,items])=>`<div class="nav-label">${group}</div>${items.map(([to,icon,label])=>`<a class="nav-link ${activeNav(r)===to?'active':''}" href="#${to}"><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('')}`).join('')}</nav><div class="sidebar-bottom"><span class="demo-dot"></span>Chế độ mô phỏng<br><span class="muted small">Không có kết nối production</span><p style="margin-top:12px">${link('Thiết kế & trạng thái','#'.replace('#','')+'components','help-link')} · ${link('Đăng nhập mẫu','login','help-link')}</p></div></aside><div class="workspace"><header class="topbar">${btn('☰','menu','mobile-menu','aria-label="Mở menu"')}<div class="breadcrumb">Không gian làm việc <span style="padding:0 12px">/</span> <strong>${E(screen?.title||'CMS')}</strong></div><div class="userbox"><span class="badge amber">STAGING · MẪU</span><span class="avatar">QT</span><div class="usertext"><strong class="small">Tài khoản minh họa</strong><small>${names[role]}</small></div></div></header><div class="demo-bar"><span><strong>PROTOTYPE</strong> · Không nhập mật khẩu, khóa API hoặc dữ liệu thật.</span><div class="demo-controls"><label for="demo-role">Vai trò thử</label><select id="demo-role">${Object.entries(names).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${v}</option>`).join('')}</select><select id="demo-state" aria-label="Trạng thái minh họa">${[['normal','Bình thường'],['loading','Đang tải'],['empty','Không có dữ liệu'],['error','Lỗi kết nối'],['forbidden','Không có quyền'],['success','Lưu thành công']].map(([k,v])=>`<option value="${k}" ${viewState===k?'selected':''}>${v}</option>`).join('')}</select>${btn('Đặt lại','reset')}</div></div><main class="main">${content}${note()}</main></div></div>`;}
function stateView(kind){if(kind==='loading')return head('Đang tải dữ liệu','Chưa có kết quả từ hệ thống.')+panel('Vui lòng chờ',`<div aria-busy="true" aria-label="Đang tải"><div class="skeleton" style="width:38%"></div>${[1,2,3,4].map(()=>'<div class="skeleton row"></div>').join('')}</div>`);const m={empty:['Chưa có dữ liệu','Bạn có thể tạo bản ghi đầu tiên hoặc thay đổi bộ lọc.','Về trạng thái mẫu'],error:['Không thể tải dữ liệu','Không hiển thị lỗi API thành “0 kết quả”. Nội dung đang nhập cần được giữ khi thử lại.','Thử lại'],forbidden:['Bạn chưa có quyền truy cập','Yêu cầu quản trị cấp đúng quyền. Trong sản phẩm thật, API cũng phải từ chối request.','Quay về tổng quan']}[kind];return head(m[0],'Trạng thái dùng chung trong CMS')+`<section class="panel"><div class="empty-state"><div class="empty-icon">${kind==='error'?'!':'◇'}</div><h2>${m[0]}</h2><p>${m[1]}</p>${btn(m[2],'normal','primary')}</div></section>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,foot],i)=>`<div class="stat ${i===0?'highlight':''}"><span class="label">${label}</span><strong>${value}</strong><span class="foot">${foot}</span></div>`).join('')}</div>`;}
function dashboard(){return head('Tổng quan vận hành','Chào bạn, đây là trạng thái không gian dữ liệu mẫu ngày 16/11/2026.',link('Xem hàng đợi duyệt →','reviews','help-link'))+stats([['Kho phim mẫu',db.movies.length,'Dữ liệu thiết kế, không phải kho thật'],['Chờ duyệt',db.movies.filter(x=>x.editorialState==='in_review').length,'Cần rà soát trước xuất bản'],['Chiến dịch mẫu',db.campaigns.filter(c=>c.status==='active').length,'Đang hoạt động trong mô phỏng'],['Doanh thu thực','Chưa có','Chờ báo cáo đối tác xác minh']])+`<div class="grid two"><div>${panel('Công việc cần xử lý',db.tasks.map((x,i)=>`<div class="list-row"><div class="number-circle">${i+1}</div><div class="grow"><strong>${x.title}</strong><span class="muted small">${x.subtitle}</span></div>${link('Xử lý →',x.route,'help-link small')}</div>`).join(''))}${panel('Phân bố báo lỗi mẫu',`<div class="chart">${[3,1,2,1,4,2,1].map((n,i)=>`<div class="bar" style="height:${n*26}px"><b>${n}</b><span>${10+i}/11</span></div>`).join('')}</div><p class="minchart-note">Số yêu cầu giả lập theo ngày. Không dùng làm báo cáo vận hành thật.</p>`)}</div><div>${panel('Kiểm tra trước khi ra mắt',`<div class="list-row"><div class="grow"><strong>Player đối tác</strong><small class="muted">Chưa có embed hoặc tài liệu</small></div>${badge('unverified')}</div><div class="list-row"><div class="grow"><strong>Quy tắc modal / floating</strong><small class="muted">Thông số đang chờ duyệt riêng</small></div>${badge('pending')}</div><div class="list-row"><div class="grow"><strong>Doanh thu & đối soát</strong><small class="muted">Chỉ có file mẫu</small></div>${badge('unverified')}</div>`)}${callout('Bản nháp không làm thay đổi web','Mọi thay đổi nội dung cần gửi duyệt và xuất bản đúng phiên bản.','blue')}${panel('Hoạt động gần đây',timeline())}</div></div>`;}
function timeline(){return `<div class="timeline">${db.audit.slice(0,3).map(x=>`<div class="timeline-item"><strong class="small">${E(x.action)}</strong><p>${E(x.detail)}</p><small>${x.time} · Dữ liệu mẫu</small></div>`).join('')}</div>`;}
function movies(){const rows=db.movies.filter(m=>(m.title+' '+m.id).toLowerCase().includes(filterText.toLowerCase())&&(!filterStatus||m.editorialState===filterStatus));return head('Kho phim','Một hồ sơ phim dùng chung cho trang chủ, tìm kiếm và màn xem phim.',btn('+ Thêm phim','new-movie','primary'))+`<section class="panel"><div class="toolbar"><div class="filters"><input id="movie-search" class="search" placeholder="Tìm tên phim hoặc mã…" aria-label="Tìm phim" value="${E(filterText)}"><select id="movie-filter" aria-label="Trạng thái phim"><option value="">Tất cả trạng thái</option>${['draft','in_review','approved'].map(x=>`<option value="${x}" ${filterStatus===x?'selected':''}>${labels[x]}</option>`).join('')}</select></div><span class="muted small">${rows.length} phim mẫu</span></div>${rows.length?table(['Phim','Loại / năm','Thể loại','Biên tập','Xuất bản',''],rows.map(m=>[`<div class="movie-cell"><div class="poster" aria-label="Ảnh giữ chỗ">MẪU</div><div><strong>${E(m.title)}</strong><div class="sub">${m.id}</div></div></div>`,`${m.type==='series'?'Phim bộ':'Phim lẻ'}<div class="sub">${m.year}</div>`,E(m.genres.join(', ')),badge(m.editorialState),badge(m.publicationState),btn('Chi tiết','select-movie','quiet',`data-id="${m.id}"`)]),`<span>Hiển thị ${rows.length} bản ghi · dữ liệu mẫu</span><span>Trang 1 / 1</span>`):'<div class="empty-state"><h2>Không có phim phù hợp</h2><p>Thử từ khóa khác hoặc xóa bộ lọc.</p></div>'}</section>`;}
function movieEdit(){const m=db.movies[selectedMovie];return head('Biên tập phim',`Bản nháp #${m.revision} · ${m.id}`,`${btn('Xem trước','preview-movie')}${btn('Lưu nháp','save-movie','primary')}`)+tabs([['Thông tin','movie-edit'],['Nguồn phát','sources'],['Tập nội bộ','episodes'],['Chi tiết & lịch sử','movie-detail']],'movie-edit')+`<div class="mobile-limited">${callout('Khuyến nghị chỉnh sửa trên desktop','Form được hiển thị để xem. Nhập liệu dài và đối soát hàng loạt cần desktop/tablet.')}</div><div class="grid two"><div><form id="movie-form">${panel('Thông tin cơ bản',`<div class="fields">${field('Tên phim <span class="required">*</span>','title',m.title,'text',true)}${field('Đường dẫn slug <span class="required">*</span>','slug',m.slug,'text',true,'Không dấu, chữ thường. Đổi slug khi đã xuất bản cần tạo chuyển hướng.')}${field('Năm phát hành *','year',m.year,'number')}${select('Loại nội dung','type',[['movie','Phim lẻ'],['series','Phim bộ']],m.type)}${field('Thể loại','genres',m.genres.join(', '),'text',true)}<label class="field full">Mô tả<textarea name="summary">${E(m.summary)}</textarea><small>Tối đa 5.000 ký tự; không chèn script.</small></label></div>`)}${panel('Thông tin tìm kiếm (SEO)',`<div class="fields">${field('Tiêu đề SEO','seoTitle',m.title,'text',true)}${field('Mô tả SEO','seoDescription','Khám phá nội dung tại Rạp Đêm.','text',true)}</div>`)}</form></div><div>${panel('Trạng thái',detail([['Biên tập',badge(m.editorialState)],['Công khai',badge(m.publicationState)],['Phiên bản live',m.publishedRevision?`#${m.publishedRevision}`:'Chưa có'],['Chỉnh sửa','Tài khoản minh họa']])+`<div class="section-spacer"></div>${btn('Gửi duyệt','submit-movie','primary')}`)}${panel('Ảnh đại diện',`<div class="poster big">POSTER MẪU</div><p class="muted small" style="text-align:center;margin-top:14px">Giữ chỗ, không phải tài nguyên production.</p>${btn('Chọn ảnh từ thư viện','asset-picker')}`)}${callout('Phim bộ đang có điều kiện','Chưa bật phát phim bộ khi chưa xác minh điều hướng tập của đối tác.','blue')}</div></div>`;}
function movieDetail(){const m=db.movies[selectedMovie];return head(E(m.title),`${m.id} · Một bộ metadata dùng cho mọi màn hình`,`${btn('Chỉnh sửa','edit-movie','primary')}${btn('Ngừng phát','withdraw-movie','danger')}`)+tabs([['Tổng quan','movie-detail'],['Nội dung','movie-edit'],['Nguồn phát','sources'],['Lịch xuất bản','publishing']],'movie-detail')+`<div class="grid two"><div>${panel('Thông tin phim',`<div class="movie-overview"><div class="poster big" style="margin:0">POSTER MẪU</div><div style="flex:1;min-width:0">${detail([['Tên',E(m.title)],['Năm',m.year],['Thể loại',E(m.genres.join(', '))],['Loại',m.type==='series'?'Phim bộ':'Phim lẻ'],['Biên tập',badge(m.editorialState)],['Xuất bản',badge(m.publicationState)]])}</div></div><p class="muted small" style="margin-top:22px">${E(m.summary)}</p>`)}${panel('Lịch sử thay đổi',timeline())}</div><div>${panel('Điều kiện xuất bản',`<div class="list-row"><div class="grow">Metadata mẫu</div>${badge('verified')}</div><div class="list-row"><div class="grow">Quyền phát thực tế</div>${badge('pending')}</div><div class="list-row"><div class="grow">Nguồn đối tác thực tế</div>${badge('unverified')}</div>`)}${callout('Live mô phỏng không phải live thật','Prototype chỉ thay trạng thái dữ liệu trong bộ nhớ trình duyệt. Không gọi website hoặc player.','blue')}</div></div>`;}
function reviews(){return head('Duyệt & xuất bản','Kiểm tra đúng phiên bản trước khi phát hành.',link('Lịch xuất bản →','publishing','help-link'))+`<section class="panel">${table(['Nội dung','Loại','Phiên bản','Người gửi','Trạng thái',''],db.movies.filter(m=>m.editorialState==='in_review').map(m=>[E(m.title),'Phim',`#${m.revision}`,'Biên tập mẫu',badge('in_review'),btn('Rà soát','select-review','quiet',`data-id="${m.id}"`)]),'<span>Chỉ revision đang chờ duyệt được xử lý</span>')}</section>`+callout('Tách người soạn và người duyệt','Nếu Chủ hệ thống tự duyệt trong đội một người, phải ghi rõ lý do. Prototype mô phỏng vai trò, không thay kiểm quyền backend.');}
function reviewDetail(){const m=db.movies[selectedMovie];return head('Rà soát thay đổi',`${m.title} · Phiên bản #${m.revision}`,`${btn('Trả sửa','reject-movie','danger')}${btn('Phê duyệt','approve-movie','primary')}`)+`<div class="steps"><span class="step done">1. Soạn nháp</span><span class="step current">2. Phê duyệt</span><span class="step">3. Xuất bản</span></div><div class="grid two"><div>${panel('So sánh nội dung',`<div class="diff"><div class="diff-item before"><small>BẢN TRƯỚC</small><h3>${E(m.title)}</h3><p class="small muted">Mô tả chưa bổ sung thông tin hiển thị.</p><span class="badge">Revision trước</span></div><div class="diff-item after"><small>BẢN GỬI DUYỆT #${m.revision}</small><h3>${E(m.title)}</h3><p class="small">${E(m.summary)}</p><span class="badge green">Nội dung mẫu cập nhật</span></div></div>`)}${panel('Checklist người duyệt',`<label class="checkrow"><input type="checkbox" checked> Metadata nhất quán với bộ phim mẫu</label><label class="checkrow"><input type="checkbox" checked> Nội dung và ảnh không vượt bố cục</label><label class="checkrow"><input type="checkbox"> Quyền phát / nguồn thật: chờ đối tác</label>`)}${callout('Duyệt thiết kế mô phỏng','Nút phê duyệt chỉ áp dụng bản ghi mẫu. Không chứng nhận quyền nội dung hoặc khả năng đối tác.','blue')}</div><div>${panel('Hồ sơ duyệt',detail([['Người gửi','Biên tập mẫu'],['Revision',`#${m.revision}`],['Trạng thái',badge(m.editorialState)],['Vai trò đang thử',names[role]]]))}${panel('Ghi chú',`<label class="field">Nhận xét<textarea id="review-comment" placeholder="Nhập lý do duyệt hoặc nội dung cần sửa…"></textarea></label>`)}</div></div>`;}
function publishing(){const m=db.movies[selectedMovie];return head('Lịch xuất bản','Theo dõi bản phát hành, không đồng nhất “đã vào hàng đợi” với “đã live”.',btn('Xuất bản mẫu đã duyệt','publish-movie','primary'))+`<section class="panel">${table(['Release / nội dung','Revision','Lịch dự kiến','Trạng thái',''],db.releases.map(r=>[`${r.id}<div class="sub">${E(r.title)}</div>`,`#${r.revision}`,r.time,badge(r.status),btn('Xem nhật ký','to-audit','quiet')]),'<span>Múi giờ hiển thị UTC+7 · dữ liệu mẫu</span>')}</section>`+`<div class="grid equal">${panel('Bản đang chọn',detail([['Phim',E(m.title)],['Biên tập',badge(m.editorialState)],['Published revision',m.publishedRevision||'Chưa có']])+btn('Hẹn giờ mẫu','schedule-movie'))}${panel('Xử lý khi lỗi',`<p class="muted small">Giữ bản công khai tốt trước đó. Retry không tạo release trùng; rollback vẫn kiểm tra nội dung đã bị gỡ hoặc hết quyền.</p>${btn('Mô phỏng lỗi tác vụ','job-error','danger')}`)}</div>`;}
function providers(){return head('Đối tác & nguồn phát','Chỉ cấu hình nguồn được phép. Iframe không tự chứng minh khả năng điều khiển.',btn('Thêm hồ sơ mẫu','generic-form','primary','data-kind="Đối tác player"'))+tabs([['Đối tác','providers'],['Nguồn theo phim','sources'],['Khả năng tích hợp','capabilities']],'providers')+callout('Chưa có đối tác thật được xác nhận','Tất cả khả năng tích hợp hiện ở trạng thái chưa xác minh. Không có video hoặc khóa API thật trong prototype.')+`<section class="panel">${table(['Đối tác','Domain','Tài liệu','Kết quả kiểm tra',''],[['Đối tác player — chờ cung cấp','Chưa cấu hình','Chưa cung cấp',badge('unverified'),link('Xem khả năng →','capabilities','help-link')]])}</section>`+panel('Dữ liệu cần trước khi tích hợp',`<div class="grid three"><div><h3>01. Embed mẫu</h3><p class="muted small">URL được phép thử, đúng phim và thiết bị.</p></div><div><h3>02. Tài liệu kỹ thuật</h3><p class="muted small">API/SDK, domain, events và giới hạn.</p></div><div><h3>03. Bằng chứng test</h3><p class="muted small">Thiết bị, phiên bản adapter, kết quả và ngày kiểm tra.</p></div></div>`);}
function sources(){const m=db.movies[selectedMovie];return head('Nguồn phát theo phim',m.title,btn('+ Thêm nguồn mẫu','source-form','primary'))+tabs([['Hồ sơ phim','movie-detail'],['Nguồn phát','sources'],['Khả năng đối tác','capabilities']],'sources')+`<section class="panel">${table(['Nguồn','Đối tác','Độ ưu tiên','Khả dụng',''],[['Nguồn mẫu 01<div class="sub">Không phát video thật</div>','Chưa xác nhận','1',badge('unverified'),btn('Kiểm tra','test-provider','quiet')]])}</section>`+callout('Không có server giả','Chỉ hiện nút đổi server khi có ít nhất hai nguồn hợp lệ cho cùng phim/tập. Không hứa giữ vị trí xem nếu đối tác không hỗ trợ.','blue');}
function capabilities(){return head('Khả năng tích hợp','Bằng chứng hỗ trợ trước khi bật chức năng.',link('← Hồ sơ đối tác','providers','help-link'))+`<section class="panel">${table(['Khả năng','Trạng thái','Bằng chứng cần','Hành vi khi chưa hỗ trợ'],[['Phát phim','Embed + phát thử','Không bật nguồn thật'],['Preroll / skip','SDK/config + ad events','Không có nút bỏ qua giả'],['Đổi server / seek','Nguồn dự phòng + test','Không hứa tiếp tục đúng thời điểm'],['Chuyển tập','Điều hướng đến mọi tập','Chặn xuất bản phim bộ'],['Video events','Callback hợp lệ','Thời lượng xem hiển thị N/A'],['Doanh thu đối tác','File/API đối soát thật','Không tính tiền từ click client']].map(([x,e,f])=>[x,badge('unverified'),e,f]))}</section>`+callout('Chưa có bằng chứng = chưa xác minh','Không chuyển thành “hỗ trợ” chỉ vì ảnh thiết kế có nút hoặc iframe tải thành công.');}
function campaigns(){return head('Chiến dịch quảng cáo','Quản lý lịch, nội dung và trạng thái phân phối.',btn('+ Tạo chiến dịch','new-campaign','primary'))+tabs([['Chiến dịch','campaigns'],['Mẫu quảng cáo','creatives'],['Vị trí','placements'],['Quy tắc','ad-rules']],'campaigns')+stats([['Chiến dịch mẫu',db.campaigns.length,'Không phải hợp đồng thật'],['Đang chạy',db.campaigns.filter(c=>c.status==='active').length,'Chỉ trong mô phỏng'],['Độc quyền',db.campaigns.filter(c=>c.mode==='exclusive').length,'Kiểm tra lịch đặt chỗ'],['Doanh thu thực','N/A','Chưa nhận báo cáo đối tác']])+`<section class="panel">${table(['Chiến dịch','Phân phối','Thiết bị','Thời gian','Trạng thái',''],db.campaigns.map(c=>[`${E(c.name)}<div class="sub">${c.id} · đối tác mẫu</div>`,c.mode==='exclusive'?'Độc quyền':c.mode==='shared'?'Chia sẻ':'Dự phòng',c.deviceClasses.join(', '),'16–22/11/2026',badge(c.status),btn(c.status==='paused'?'Đã tạm dừng':'Tạm dừng','pause-campaign','quiet',`data-id="${c.id}" ${c.status==='paused'?'disabled':''}`)]))}</section>`+callout('Tạm dừng khác hủy đặt chỗ','Chiến dịch dừng vẫn giữ vị trí đã bán. Muốn giải phóng lịch cần hủy đặt chỗ có lý do.','blue');}
function campaignEdit(){return head('Tạo chiến dịch','Soạn cấu hình trước, gửi duyệt sau. Chưa kích hoạt quảng cáo thật.',btn('Lưu nháp mẫu','save-campaign','primary'))+`<div class="grid two"><form id="campaign-form">${panel('Thông tin chiến dịch',`<div class="fields">${field('Tên chiến dịch *','name','Đồng hành tháng 11','text',true)}${select('Đối tác','partner',[['demo-partner','Đối tác minh họa']],'demo-partner')}${select('Chế độ phân phối','mode',[['exclusive','Độc quyền theo lịch'],['shared','Chia sẻ theo trọng số']],'exclusive')}${field('Bắt đầu (UTC+7)','startsAt','2026-11-16T00:00','datetime-local')}${field('Kết thúc (UTC+7)','endsAt','2026-11-23T00:00','datetime-local')}<div class="field full">Thiết bị<div class="tag-list"><span class="chip">Desktop</span><span class="chip">Tablet</span><span class="chip">Mobile</span></div><small>Phạm vi cuối cùng phải khớp từng slot được gán.</small></div></div>`)}${panel('Phân phối và vị trí',`<p class="muted small">Độc quyền cần đặt chỗ được xác nhận; chia sẻ cần creative hợp lệ và trọng số.</p>${link('Mở lịch đặt chỗ →','reservations','help-link')}`)}</form><div>${panel('Trước khi kích hoạt',`<div class="list-row">1. Chốt thời gian và thiết bị</div><div class="list-row">2. Chọn mẫu quảng cáo đã duyệt</div><div class="list-row">3. Kiểm tra vị trí / trùng lịch</div><div class="list-row">4. Gửi duyệt đúng revision</div>`)}${callout('Không đặt giá giả','Đơn giá và mô hình tính tiền sẽ theo hợp đồng đối tác. Prototype không tự tính doanh thu từ số lượt hiển thị.')}</div></div>`;}
function placements(){return head('Vị trí quảng cáo','Các slot cố định cần khớp frontend, không tự sinh layout mới.',link('Quy tắc an toàn →','ad-rules','help-link'))+tabs([['Chiến dịch','campaigns'],['Mẫu quảng cáo','creatives'],['Vị trí','placements'],['Quy tắc','ad-rules']],'placements')+`<section class="panel">${table(['Slot ID','Trang / thiết bị','Định dạng','Kích thước CSS','Trạng thái'],db.placements.map(p=>[`<span class="code">${p.id}</span>`,`${p.route} / ${p.device}`,p.format,`${p.width} × ${p.height}`,badge(p.pending?'pending':'draft')]))}</section>`+callout('Thông số ảnh thiết kế không phải CSS','Các kích thước hiển thị ở đây là giá trị đề xuất V18, còn chờ duyệt riêng. Rails ẩn khi không đủ không gian; không nhồi toàn bộ xuống mobile.','blue');}
function reservations(){return head('Lịch đặt chỗ quảng cáo','Lịch tuần 16–22/11/2026 · UTC+7 · mỗi ô là một vị trí/thiết bị.',btn('+ Đặt chỗ','new-reservation','primary'))+`<section class="panel"><div class="panel-head"><h2>Tuần 47 · Tháng 11/2026</h2><div class="tag-list"><span class="badge amber">Độc quyền</span><span class="badge blue">Chia sẻ</span><span class="badge">Giữ chỗ khi tạm dừng</span></div></div><div class="table-scroll"><div class="calendar"><div class="cal-head">Vị trí / thiết bị</div>${['T2 · 16','T3 · 17','T4 · 18','T5 · 19','T6 · 20','T7 · 21','CN · 22'].map(x=>`<div class="cal-head">${x}</div>`).join('')}${['HOME_TOP_DESKTOP','WATCH_INLINE_DESKTOP','HOME_FLOAT_MOBILE'].map((p,j)=>`<div><strong>${p.replaceAll('_',' ')}</strong></div>${Array.from({length:7},(_,i)=>`<div>${j===0&&i<4?`<div class="booking">Đối tác A<br>Độc quyền</div>`:j===1?`<div class="booking shared">Nhóm chia sẻ<br>60 / 40</div>`:j===2&&i<3?`<div class="booking hold">Chờ duyệt cap</div>`:'<span class="muted">Trống</span>'}</div>`).join('')}`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>Đặt chỗ mẫu đã ghi nhận</h2></div>${table(['Mã / chiến dịch','Vị trí','Bắt đầu','Kết thúc','Trạng thái',''],db.reservations.map(r=>[`${r.id}<div class="sub">${r.campaignId}</div>`,r.placementIds.join(', '),r.startsAt.slice(0,10),r.endsAt.slice(0,10),badge(r.status),btn('Hủy đặt chỗ','cancel-reservation','quiet',`data-id="${r.id}" ${r.status==='cancelled'?'disabled':''}`)]))}</section>`+callout('Khoảng thời gian [bắt đầu, kết thúc)','Một đặt chỗ kết thúc đúng lúc đặt chỗ khác bắt đầu không bị coi là trùng. Xác nhận phải kiểm tra lại trong transaction phía server.','blue');}
function reservationNew(){return head('Tạo đặt chỗ độc quyền','Kiểm tra xung đột trên từng vị trí và thiết bị trước khi xác nhận.',link('← Lịch quảng cáo','reservations','help-link'))+`<div class="grid two"><div><form id="reservation-form">${panel('Phạm vi đặt chỗ',`<div class="fields">${select('Chiến dịch','campaignId',db.campaigns.filter(c=>c.mode==='exclusive').map(c=>[c.id,c.name]),db.campaigns[0].id,true)}${select('Vị trí / thiết bị *','placementId',db.placements.map(p=>[p.id,p.id]),'HOME_TOP_DESKTOP',true)}${field('Bắt đầu (UTC+7) *','startsAt','2026-11-17T00:00','datetime-local')}${field('Kết thúc (UTC+7) *','endsAt','2026-11-19T00:00','datetime-local')}${select('Khi mẫu quảng cáo tải lỗi','fallback',[['collapse','Không hiển thị quảng cáo'],['approved_house','Nội dung dự phòng đã duyệt']],'collapse',true)}${field('Ghi chú *','reason','Đặt vị trí theo thỏa thuận mẫu','text',true)}</div><div id="booking-result" style="margin-top:18px" aria-live="polite"></div><div class="actions" style="margin-top:18px">${btn('Kiểm tra trùng lịch','check-booking')}${btn('Xác nhận mẫu','confirm-booking','primary')}</div>`)}</form></div><div>${panel('Quy tắc giữ chỗ',`<div class="list-row">Không xác nhận hai đặt chỗ độc quyền chồng nhau.</div><div class="list-row">Chiến dịch tạm dừng vẫn giữ chỗ.</div><div class="list-row">Chỉ hủy đặt chỗ mới giải phóng lịch.</div><div class="list-row">Không tự thay bằng đối tác trả tiền khác khi tải lỗi.</div>`)}${callout('Thử tình huống xung đột','Dữ liệu mặc định 17–19/11 trùng đặt chỗ mẫu. Đổi sang 20–22/11 để thử xác nhận hợp lệ.','blue')}</div></div>`;}
function adRules(){return head('Quy tắc phân phối & an toàn','Độc quyền → chia sẻ hợp lệ → dự phòng → không hiển thị.',btn('Tắt quảng cáo mẫu','kill-ads','danger'))+tabs([['Chiến dịch','campaigns'],['Mẫu quảng cáo','creatives'],['Vị trí','placements'],['Quy tắc','ad-rules']],'ad-rules')+`<div class="grid equal">${panel('Phân phối theo vị trí',`<div class="list-row"><div class="number-circle">1</div><div><strong>Kiểm tra điều kiện</strong><div class="muted small">Đúng slot / thiết bị / lịch / phê duyệt</div></div></div><div class="list-row"><div class="number-circle">2</div><div><strong>Độc quyền còn hiệu lực</strong><div class="muted small">Không bị chiến dịch chia sẻ chiếm chỗ</div></div></div><div class="list-row"><div class="number-circle">3</div><div><strong>Chia sẻ theo trọng số</strong><div class="muted small">60/40 là mục tiêu, không cam kết từng nhóm 10 lượt</div></div></div><div class="list-row"><div class="number-circle">4</div><div><strong>Dự phòng hoặc bỏ slot</strong><div class="muted small">Không chặn người xem khi không có quảng cáo</div></div></div>`)}${panel('Giới hạn hiển thị — chờ duyệt',detail([['Modal HOME','Đề xuất 1 lần/24h + 1 lần/phiên'],['Floating','Đề xuất ≥8 giây + cuộn ≥25%'],['Đóng floating','Đề xuất nghỉ 24 giờ'],['Xung đột','Không modal + floating cùng lúc'],['Vùng bảo vệ','Ẩn khi player / footer / menu / bàn phím'],['Production flags',badge('pending')]]))}</div>`+callout('Chưa bật thông số production','Việc duyệt CMS V2 không tự động duyệt tần suất, đơn giá, kích thước slot hoặc tích hợp preroll.');}
function analytics(){return head('Thống kê nội dung & quảng cáo','Ví dụ cách đọc số liệu. Các số dưới đây là dữ liệu giả lập.',link('Đối soát doanh thu →','statements','help-link'))+stats([['Yêu cầu quảng cáo mẫu','1.200','internal · ad_request'],['Tải thành công mẫu','900','internal · ad_loaded'],['Visible nội bộ mẫu','650','Không phải billable impression'],['Doanh thu đối tác','N/A','Chưa có dữ liệu thật']])+panel('Hiệu quả theo vị trí (mẫu)',table(['Vị trí','Request','Loaded','Visible nội bộ','Click','Lỗi'],[['HOME_TOP_DESKTOP','600','480','350','8','12'],['WATCH_INLINE_DESKTOP','400','300','210','4','10'],['HOME_FLOAT_MOBILE','200','120','90','2','8']]))+`<div class="grid equal">${callout('Không suy lượt phát từ iframe','Thời lượng xem và sự kiện play chỉ có khi đối tác cung cấp callback đã xác minh.','blue')}${callout('Không suy tiền từ click','Doanh thu được xác nhận và tiền thực nhận là hai nhóm dữ liệu riêng.')}</div>`;}
function statements(){return head('Đối soát doanh thu','Phân biệt số đối tác xác nhận với tiền đã nhận. Dữ liệu minh họa.',`${link('Nhập báo cáo','revenue-import','help-link')}${btn('Mở kỳ mẫu','to-statement','primary')}`)+tabs([['Kỳ đối soát','statements'],['Nhập báo cáo','revenue-import'],['Khoản thực nhận','payments']],'statements')+stats([['Doanh thu thật','N/A','Chưa có đối tác xác nhận'],['Kỳ đối soát mẫu','1','Tháng 11/2026'],['Trạng thái kỳ',labels[db.statement.status],'Thay đổi trong mô phỏng'],['Nguồn dữ liệu','CSV mẫu','Không phải báo cáo đối tác thật']])+`<section class="panel">${table(['Kỳ / đối tác','Đơn vị','Gộp (mẫu)','Điều chỉnh','Ròng (mẫu)','Trạng thái',''],[['11/2026 · Đối tác mẫu','VND','12.000.000','−500.000','11.500.000',badge(db.statement.status),link('Chi tiết →','statement-detail','help-link')]])}</section>`+callout('Chỉ ghi nhận, không chuyển tiền','CMS không phải cổng thanh toán. Không cộng tiền khác currency khi chưa có chính sách quy đổi.','blue');}
function revenueImport(){return head('Nhập báo cáo đối tác','Dùng bộ CSV mẫu để kiểm tra cấu trúc và chống nhập trùng.',link('← Kỳ đối soát','statements','help-link'))+`<div class="steps"><span class="step done">1. Chọn đối tác / kỳ</span><span class="step current">2. Kiểm tra file</span><span class="step">3. Xác nhận nhập</span></div><div class="grid two"><div>${panel('File mẫu được cung cấp',`<div class="fields">${select('Đối tác','partner',[['demo','Đối tác minh họa']],'demo')}${field('Kỳ','period','11/2026')}${field('Tiền tệ','currency','VND')}${field('Múi giờ nguồn','timezone','Asia/Bangkok')}</div><div class="callout blue" style="margin-top:20px">Prototype chỉ nạp fixture nội bộ; không tải file riêng tư hoặc gửi dữ liệu ra mạng.</div><div class="actions">${btn('Kiểm tra CSV mẫu','validate-import')}${btn('Xác nhận nhập mẫu','commit-import','primary')}</div><div id="import-result" aria-live="polite" style="margin-top:18px"></div>`)}${panel('Xem trước dữ liệu mẫu',table(['Ngày','Slot','Billable mẫu','Doanh thu mẫu'],[['16/11/2026','HOME_TOP_DESKTOP','1.000','120.000 VND'],['16/11/2026','WATCH_INLINE_DESKTOP','500','60.000 VND']]))}</div><div>${panel('Kiểm tra trước khi nhập',`<div class="list-row">File đúng mẫu và kỳ dữ liệu</div><div class="list-row">Đối tác / timezone / currency rõ</div><div class="list-row">Không cộng trùng checksum/importId</div><div class="list-row">Không đổi dòng lỗi thành số 0</div><div class="list-row">Không chốt doanh thu chỉ vì import xong</div>`)}</div></div>`;}
function statementDetail(){return head('Kỳ đối soát tháng 11/2026','Đối tác minh họa · VND · UTC+7',`${btn('Xác nhận kỳ mẫu','confirm-statement','primary')}${btn('Khóa kỳ','lock-statement')}`)+`<div class="grid two"><div>${panel('Tóm tắt đối soát',table(['Khoản mục','Nguồn','Số tiền minh họa'],[['Doanh thu gộp','CSV mẫu','12.000.000 VND'],['Điều chỉnh','Giải trình mẫu','−500.000 VND'],['Doanh thu ròng','Gộp + điều chỉnh','11.500.000 VND'],['Thực nhận đã phân bổ','Khoản thanh toán mẫu','5.000.000 VND'],['Còn phải thu','Ròng − đã nhận','6.500.000 VND']]))}${panel('Giải trình',`<p class="small">Khoản điều chỉnh giả lập phục vụ thiết kế luồng phê duyệt. Không phải nghĩa vụ tài chính thật.</p><label class="field">Nhận xét<textarea id="statement-note">Dữ liệu mẫu đã được đối chiếu về cùng kỳ và tiền tệ.</textarea></label>`)}</div><div>${panel('Trạng thái kỳ',detail([['Trạng thái',badge(db.statement.status)],['Người lập','Báo cáo mẫu'],['Nguồn','Fixture nội bộ'],['Sau khi khóa','Điều chỉnh qua bản ghi bổ sung, không ghi đè']]))}${callout('Người lập không tự chốt','Chủ/Quản trị duyệt kỳ; người nhập có thể gửi duyệt. Vai trò Báo cáo không được tự xác nhận.','blue')}</div></div>`;}
function reports(){return head('Báo lỗi & hỗ trợ','Yêu cầu từ khách không cần đăng nhập.',link('Công việc của tôi →','tasks','help-link'))+`<section class="panel">${table(['Yêu cầu','Phim / nguồn','Loại lỗi','Ưu tiên','Trạng thái',''],db.reports.map(r=>[`${r.id}<div class="sub">16/11/2026 · dữ liệu mẫu</div>`,E(r.movie),'Không phát được',`<span class="badge ${r.priority==='Cao'?'red':''}">${r.priority}</span>`,badge(r.status),btn('Xử lý','select-report','quiet',`data-id="${r.id}"`)]))}</section>`+callout('Thông tin tối thiểu','Không bắt khách cung cấp email; không tự hứa phản hồi cá nhân nếu không có thông tin liên hệ. Không lưu token player trong ticket.','blue');}
function reportDetail(){const r=db.reports[db.selectedReport||0];return head(`Yêu cầu ${r.id}`,r.movie,`${btn('Bắt đầu xử lý','start-report','primary')}${btn('Đánh dấu đã xử lý','resolve-report')}`)+`<div class="grid two"><div>${panel('Thông tin khách báo',`<div class="list-row"><span class="badge red">Không phát được</span>${badge(r.status)}</div><p style="margin-top:15px">“Mở phim nhưng trình phát vẫn đang tải.”</p>${detail([['Thiết bị','Mobile · dữ liệu mẫu'],['Nguồn','Chưa xác minh'],['Thời gian','16/11/2026 09:18 UTC+7'],['Email','Không thu thập']])}`)}${panel('Ghi chú xử lý',`<label class="field">Ghi chú nội bộ<textarea id="report-resolution" placeholder="Ghi cách kiểm tra, kết quả và phiên bản sửa…"></textarea></label><div class="actions" style="margin-top:15px">${btn('Lưu ghi chú mẫu','save-report-note')}${btn('Yêu cầu gỡ khẩn','takedown','danger')}</div>`)}</div><div>${panel('Phân công',detail([['Người xử lý','Hỗ trợ mẫu'],['Ưu tiên',r.priority],['Trạng thái',badge(r.status)]]))}${callout('Hỗ trợ không tự gỡ phim','Hỗ trợ gửi yêu cầu; Chủ/Quản trị quyết định gỡ hoặc tắt nguồn theo quyền.')}</div></div>`;}
function site(){return head('Giao diện website','Một cấu hình dùng chung cho desktop, tablet và mobile.',btn('Lưu nháp cấu hình','save-config','primary'))+tabs([['Nội dung chung','site'],['Section trang chủ','sections'],['Trang thông tin','pages']],'site')+`<div class="grid two"><div><form id="site-form">${panel('Hero & tìm kiếm',`<div class="fields">${field('Tiêu đề','heroTitle',db.site.heroTitle,'text',true)}${field('Hướng dẫn','heroHint',db.site.heroHint,'text',true)}${field('Placeholder tìm kiếm','searchPlaceholder',db.site.searchPlaceholder,'text',true)}</div>`)}${panel('Footer dùng chung',`<div class="grid three">${db.site.footer.map(group=>`<div><h3>${E(group.heading)}</h3><div class="tag-list">${group.links.map(x=>`<span class="chip">${E(x.label)}</span>`).join('')}</div></div>`).join('')}</div><p class="muted small" style="margin-top:18px">Thay cách xếp cột theo thiết bị, không bỏ liên kết.</p>`)}</form></div><div>${panel('Xem trước nội dung',`<div style="background:#181d27;color:white;border-radius:10px;padding:25px"><span style="color:#f1c55f;font-size:12px">RẠP ĐÊM</span><h2 style="font-size:26px;margin:18px 0">${E(db.site.heroTitle)}</h2><p style="color:#c0c8d6;font-size:12px">${E(db.site.heroHint)}</p><div style="background:white;color:#9da5b0;border-radius:7px;padding:12px;font-size:11px">${E(db.site.searchPlaceholder)}</div></div>`)}${callout('Chưa đưa lên website','Lưu tại đây chỉ đổi cấu hình nháp trong prototype. Cấu hình thật phải qua duyệt và xuất bản.','blue')}</div></div>`;}
function staff(){return head('Nhân sự nội bộ','Không có tài khoản khách hoặc đối tác quảng cáo ở MVP.',btn('+ Mời nhân sự mẫu','invite-staff','primary'))+tabs([['Nhân sự','staff'],['Vai trò & quyền','roles'],['Nhật ký','audit']],'staff')+`<section class="panel">${table(['Nhân sự','Vai trò','MFA','Trạng thái',''],[['Chủ hệ thống mẫu<div class="sub">owner@example.invalid</div>','Chủ hệ thống','Mô phỏng',badge('active'),'Chủ cuối cùng: bảo vệ'],['Biên tập mẫu<div class="sub">editor@example.invalid</div>','Biên tập','Mô phỏng',badge('active'),btn('Khóa mẫu','lock-staff','quiet')],['Hỗ trợ mẫu<div class="sub">support@example.invalid</div>','Hỗ trợ','Mô phỏng',badge('active'),btn('Xem quyền','to-roles','quiet')]])}</section>`+callout('Không có xác thực thật ở prototype','Bộ chọn vai trò phía trên chỉ phục vụ duyệt UI. Không dùng làm giải pháp bảo mật production.');}
function roles(){const actions=['Sửa metadata phim','Gửi duyệt','Duyệt / xuất bản','Soạn chiến dịch','Tạm dừng campaign','Chốt kỳ đối soát','Gỡ khẩn toàn hệ thống','Quản lý quyền'];const values=[['✓','✓','✓','—','—','—'],['✓','✓','✓','—','—','—'],['✓','✓','—','—','—','—'],['✓','✓','—','✓','—','—'],['✓','✓','—','✓','—','—'],['✓','✓','—','—','—','—'],['✓','✓','—','—','—','—'],['✓','—','—','—','—','—']];return head('Vai trò & quyền','Quyền ở backend là bắt buộc; ẩn nút không thay kiểm quyền.',link('← Nhân sự','staff','help-link'))+`<section class="panel">${table(['Hành động','Chủ','Quản trị','Biên tập','Quảng cáo','Báo cáo','Hỗ trợ'],actions.map((a,i)=>[a,...values[i]]))}</section>`+callout('Ma trận rút gọn cho màn thiết kế','Danh sách quyền theo từng API nằm trong bộ contract. Tài khoản một người có thể kiêm vai trò; tự duyệt phải có lý do và audit.','blue');}
function loginScreen(mode){const mfa=mode==='mfa',recover=mode==='recover';return `<div class="login"><section class="login-brand"><div class="brand"><span class="brand-symbol">R</span><div><strong>RẠP ĐÊM</strong><small>MANAGEMENT STUDIO</small></div></div><div><div class="eyebrow">KHÔNG GIAN VẬN HÀNH</div><h1>Nội dung được duyệt.<br>Vận hành rõ ràng.</h1><p>Quản lý phim, quảng cáo và báo cáo trong một không gian dành riêng cho nhân sự.</p><div class="login-art"><div class="line gold"></div><div class="line"></div><div class="line" style="width:90%"></div><div class="line" style="width:75%"></div></div></div><small class="muted">CMS V2 · Thiết kế mô phỏng · Không có đăng nhập thật</small></section><section class="login-form"><form id="login-form"><span class="badge amber">PROTOTYPE KHÔNG XÁC THỰC THẬT</span><h2 style="margin-top:24px">${mfa?'Xác thực bổ sung':recover?'Khôi phục truy cập':'Chào mừng trở lại'}</h2><p class="muted">${mfa?'Nhập mã mẫu để xem luồng.':recover?'Mô phỏng phản hồi khôi phục, không gửi email.':'Truy cập không gian quản trị Rạp Đêm.'}</p>${mfa?field('Mã xác thực mẫu','otp','123456'):field('Email mẫu','email','admin@example.invalid','email')}${!mfa&&!recover?`<label class="field">Mật khẩu<input type="password" value="demo-only" disabled><small class="password-note">Không nhập mật khẩu thật. Không tạo session server.</small></label>`:''}${btn(mfa?'Xác nhận mã mẫu':recover?'Xem phản hồi khôi phục':'Tiếp tục mô phỏng',mfa?'login-done':recover?'recover-demo':'login-next','primary')}<p style="margin-top:18px">${link(recover||mfa?'← Về đăng nhập':'Quên mật khẩu?',recover||mfa?'login':'recover','help-link small')}</p><p class="login-small">Tài khoản dành cho nhân sự nội bộ. Không đăng ký hội viên hoặc khách hàng tại đây.</p></form></section></div>`;}
